import{_ as t,o as a,c as r,a0 as s}from"./chunks/framework.BxrwG5q5.js";const g=JSON.parse('{"title":"Percentage Rollouts","description":"","frontmatter":{},"headers":[],"relativePath":"features/rollouts.md","filePath":"features/rollouts.md"}'),n={name:"features/rollouts.md"};function i(o,e,l,u,d,c){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="percentage-rollouts" tabindex="-1">Percentage Rollouts <a class="header-anchor" href="#percentage-rollouts" aria-label="Permalink to &quot;Percentage Rollouts&quot;">​</a></h1><blockquote><p>See also: <a href="/config/features/targeting.html">Targeting Rules</a> · <a href="/config/features/segments.html">Segments</a> · <a href="/config/features/environments.html">Environments</a></p></blockquote><p>Percentage rollouts are the standard mechanism for <strong>canary releases</strong> and <strong>progressive delivery</strong> — gradually exposing a new feature to an increasing percentage of users rather than shipping to everyone at once.</p><p>Start at 5%, validate metrics, increase to 20%, 50%, then 100%. Each step is a canary stage. Rollouts are evaluated after <a href="/config/features/targeting.html">targeting rules</a> in the pipeline.</p><h2 id="sticky-bucketing" tabindex="-1">Sticky Bucketing <a class="header-anchor" href="#sticky-bucketing" aria-label="Permalink to &quot;Sticky Bucketing&quot;">​</a></h2><p>Rollouts use <strong>sticky bucketing</strong> via MurmurHash3: <code>hash(flagKey + &quot;:&quot; + userId) % 100</code>.</p><p>Sticky bucketing means the same user always lands in the same bucket for a given flag — their experience is consistent across sessions, devices, and deploys. This is a requirement for valid canary analysis: you can&#39;t measure impact if users flip in and out of the treatment group.</p><ul><li>Different flags give the same user different buckets (independent rollouts)</li><li>No session storage or cookies required — purely derived from userId</li></ul><h2 id="setting-up-a-rollout" tabindex="-1">Setting Up a Rollout <a class="header-anchor" href="#setting-up-a-rollout" aria-label="Permalink to &quot;Setting Up a Rollout&quot;">​</a></h2><ol><li>Open a config in the portal</li><li>Expand the <strong>Rollout</strong> section</li><li>Set the percentage (e.g., 20)</li><li>Set the rollout value (the canary variant)</li><li>Save</li></ol><h2 id="progressive-delivery-ramping-up" tabindex="-1">Progressive Delivery: Ramping Up <a class="header-anchor" href="#progressive-delivery-ramping-up" aria-label="Permalink to &quot;Progressive Delivery: Ramping Up&quot;">​</a></h2><p>Since bucketing is deterministic, ramping up percentage is purely additive:</p><table tabindex="0"><thead><tr><th>Change</th><th>Effect</th></tr></thead><tbody><tr><td>20% → 50%</td><td>All users who were in the 20% bucket remain. An additional ~30% of users are added (buckets 20–49).</td></tr><tr><td>50% → 20%</td><td>Users with buckets 20–49 are removed. Users with buckets 0–19 remain.</td></tr><tr><td>100% → 0%</td><td>Everyone reverts to the default value — effectively a <strong>kill switch</strong>.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Safe ramp-up</p><p>Going 5% → 10% → 25% → 50% → 100% is safe. The first 5% of users remain consistent throughout the entire ramp-up — a key property of progressive delivery.</p></div><h2 id="kill-switch" tabindex="-1">Kill Switch <a class="header-anchor" href="#kill-switch" aria-label="Permalink to &quot;Kill Switch&quot;">​</a></h2><p>Setting rollout to <code>0%</code> (or setting the flag&#39;s default value and removing the rollout) is the standard <strong>kill switch</strong> pattern — instant revert to the safe state for all users with zero code deploy.</p><h2 id="ring-based-deployment" tabindex="-1">Ring-Based Deployment <a class="header-anchor" href="#ring-based-deployment" aria-label="Permalink to &quot;Ring-Based Deployment&quot;">​</a></h2><p>Combine rollouts with <a href="/config/features/targeting.html">targeting rules</a> and <a href="/config/features/segments.html">segments</a> to implement <strong>ring deployments</strong> — rolling out through concentric rings of users by risk tolerance:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ring 0 (internal): Target segment &quot;Employees&quot; → always enabled</span></span>
<span class="line"><span>Ring 1 (canary):   Rollout 5% of all users</span></span>
<span class="line"><span>Ring 2 (early):    Rollout 25%</span></span>
<span class="line"><span>Ring 3 (general):  Rollout 100%</span></span></code></pre></div><p>Targeting rules have higher priority than rollouts in the evaluation pipeline, so ring 0 users always get the feature regardless of percentage.</p><h2 id="a-b-testing" tabindex="-1">A/B Testing <a class="header-anchor" href="#a-b-testing" aria-label="Permalink to &quot;A/B Testing&quot;">​</a></h2><p>A rollout to exactly 50% with a control (default) and a treatment (rollout value) is a standard <strong>A/B test</strong>. The sticky bucketing guarantees each user is consistently in one group for the duration of the experiment.</p><p>For <strong>multivariate tests</strong> (A/B/C/n), use multiple flags with independent rollout percentages — each flag represents one variant.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>A <code>userId</code> must be in the SDK context for rollout to work</li><li>Without a userId, rollout is skipped and the default value is returned</li><li>The userId must be stable — don&#39;t use random session IDs or sticky bucketing breaks</li></ul><h2 id="consistency-across-modes" tabindex="-1">Consistency Across Modes <a class="header-anchor" href="#consistency-across-modes" aria-label="Permalink to &quot;Consistency Across Modes&quot;">​</a></h2><p>The same hashing algorithm runs in both server-side evaluation (client keys) and client-side evaluation (server keys). A user bucketed at 30% in one mode will be at 30% in the other — no flip-flopping during migration.</p><h2 id="edge-cases" tabindex="-1">Edge Cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge Cases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Behavior</th></tr></thead><tbody><tr><td><code>rolloutPercentage: 0</code></td><td>Rollout skipped; pipeline continues to default</td></tr><tr><td><code>rolloutPercentage: 100</code></td><td>Everyone gets the rollout value (equivalent to changing the default)</td></tr><tr><td>No <code>userId</code> in context</td><td>Rollout skipped; pipeline continues to default</td></tr><tr><td>Same user, different flags</td><td>Different buckets (flag key is part of the hash input)</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/features/targeting.html">Targeting Rules</a> — Targeting takes priority over rollouts; combine for ring deployments</li><li><a href="/config/features/segments.html">Segments</a> — Define audience groups (internal users, beta cohort) for ring 0/1 targeting</li><li><a href="/config/features/environments.html">Environments</a> — Run independent canary rollouts per environment</li><li><a href="/config/features/audit-log.html">Audit Log</a> — Track rollout percentage changes over time</li><li><a href="/config/guide/scopes.html">Configuration Scopes</a> — Full evaluation pipeline</li></ul>`,31)])])}const p=t(n,[["render",i]]);export{g as __pageData,p as default};
